import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BgSoyxN5.js";const h=JSON.parse('{"title":"Terms of Service","description":"TickerForge Terms of Service for the website, software analytics tools, Telegram bot workflows, subscriptions, and related services.","frontmatter":{"title":"Terms of Service","description":"TickerForge Terms of Service for the website, software analytics tools, Telegram bot workflows, subscriptions, and related services."},"headers":[],"relativePath":"terms.md","filePath":"terms.md","lastUpdated":1784025354000}'),i={name:"terms.md"};function s(n,e,c,l,d,p){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="terms-of-service" tabindex="-1">Terms of Service <a class="header-anchor" href="#terms-of-service" aria-label="Permalink to &quot;Terms of Service&quot;">​</a></h1><p><em>Last updated: 14 July 2026</em></p><p>These Terms of Service (&quot;Terms&quot;) govern access to and use of the TickerForge website, widgets, Telegram bot workflows, software analytics tools, paid subscriptions, content, and related services (collectively, the &quot;Service&quot;).</p><p>TickerForge is operated by <strong>Anton Tkach</strong>, trading as <strong>TickerForge</strong>.</p><p>By using TickerForge, you agree to these Terms. If you do not agree, do not use the Service.</p><h2 id="_1-product-description" tabindex="-1">1. Product Description <a class="header-anchor" href="#_1-product-description" aria-label="Permalink to &quot;1. Product Description&quot;">​</a></h2><p>TickerForge is a software-as-a-service platform for investing decision support, stock research workflows, watchlist monitoring, portfolio diagnostics, market regime context, screener views, and educational analytics.</p><p>TickerForge is software. It does not provide brokerage services, trade execution, custody, portfolio management, or personalized advisory services.</p><h2 id="_2-no-financial-advice" tabindex="-1">2. No Financial Advice <a class="header-anchor" href="#_2-no-financial-advice" aria-label="Permalink to &quot;2. No Financial Advice&quot;">​</a></h2><p>TickerForge does not provide financial, investment, tax, legal, or trading advice. Outputs shown by the Service are educational research materials and software-generated analytics based on available market, company, portfolio, and user-provided inputs.</p><p>You are responsible for your own investment decisions. TickerForge does not create a fiduciary, adviser-client, broker-client, or portfolio-management relationship with you.</p><p>Data, models, scores, research alerts, and diagnostics may be delayed, incomplete, inaccurate, or affected by third-party data limitations. Always verify information before relying on it.</p><h2 id="_3-accounts-and-access" tabindex="-1">3. Accounts and Access <a class="header-anchor" href="#_3-accounts-and-access" aria-label="Permalink to &quot;3. Accounts and Access&quot;">​</a></h2><p>Some features may be available without an account. Other features may require email registration, Telegram connection, or a paid subscription.</p><p>You are responsible for maintaining access to your email account, Telegram account, and any device used to access TickerForge. We may suspend or restrict access if we detect abuse, security risks, payment failure, or violation of these Terms.</p><h2 id="_4-subscriptions-and-payments" tabindex="-1">4. Subscriptions and Payments <a class="header-anchor" href="#_4-subscriptions-and-payments" aria-label="Permalink to &quot;4. Subscriptions and Payments&quot;">​</a></h2><p>TickerForge may offer Free, Standard, Pro, early-access, or other paid plans. Pricing and plan details are shown on the <a href="/pricing">Pricing page</a>.</p><p>Subscriptions may be billed through a third-party payment provider, reseller, or merchant-of-record flow. The provider may appear on receipts, invoices, checkout pages, or card statements.</p><p>Where payment methods are offered, such as card checkout, Telegram Stars, or another provider, the provider&#39;s own terms and payment flow may also apply.</p><p>Subscription access begins after successful payment or activation. Paid access may be cancelled, expire, renew, or be suspended according to the payment provider, plan rules, and applicable law.</p><p>Cancellation stops future renewal unless the provider states otherwise. It does not automatically refund the current paid period. Refund requests are reviewed under the Refund and Cancellation Policy and may depend on usage, timing, provider rules, and applicable law.</p><h2 id="_5-acceptable-use" tabindex="-1">5. Acceptable Use <a class="header-anchor" href="#_5-acceptable-use" aria-label="Permalink to &quot;5. Acceptable Use&quot;">​</a></h2><p>You agree not to:</p><ul><li>use TickerForge for illegal, abusive, fraudulent, or misleading activity;</li><li>resell, scrape, reverse engineer, or copy the Service without permission;</li><li>attempt to access another user&#39;s data;</li><li>overload, disrupt, or interfere with the Service;</li><li>use TickerForge outputs as if they were personalized advice, brokerage instructions, or guaranteed outcomes;</li><li>publish or redistribute restricted paid content without authorization.</li></ul><h2 id="_6-user-inputs-and-portfolio-data" tabindex="-1">6. User Inputs and Portfolio Data <a class="header-anchor" href="#_6-user-inputs-and-portfolio-data" aria-label="Permalink to &quot;6. User Inputs and Portfolio Data&quot;">​</a></h2><p>If you submit tickers, holdings, cash amounts, portfolio screenshots, or similar inputs, you confirm that you have the right to provide that data. TickerForge uses submitted data to generate software analytics, diagnostics, snapshots, and monitoring outputs.</p><p>TickerForge does not ask for broker login credentials, account passwords, identity documents, or full brokerage statements for the browser portfolio workflow.</p><h2 id="_7-intellectual-property" tabindex="-1">7. Intellectual Property <a class="header-anchor" href="#_7-intellectual-property" aria-label="Permalink to &quot;7. Intellectual Property&quot;">​</a></h2><p>TickerForge owns or licenses the software, branding, design, models, content, documentation, reports, interfaces, and other materials used in the Service.</p><p>You may use the Service for your own research workflows. You may not copy, clone, resell, redistribute, or create derivative products from TickerForge materials without written permission.</p><h2 id="_8-service-availability-and-changes" tabindex="-1">8. Service Availability and Changes <a class="header-anchor" href="#_8-service-availability-and-changes" aria-label="Permalink to &quot;8. Service Availability and Changes&quot;">​</a></h2><p>TickerForge may change, pause, limit, or discontinue features at any time. Beta and early-access features may be incomplete, experimental, or changed without notice.</p><p>The Service is provided &quot;as is&quot; and &quot;as available.&quot; We do not guarantee uninterrupted access, data availability, model accuracy, or compatibility with every device or platform.</p><h2 id="_9-limitation-of-liability" tabindex="-1">9. Limitation of Liability <a class="header-anchor" href="#_9-limitation-of-liability" aria-label="Permalink to &quot;9. Limitation of Liability&quot;">​</a></h2><p>To the maximum extent permitted by law, TickerForge, its operator, owners, contributors, contractors, and service providers are not liable for indirect, incidental, special, consequential, punitive, market, trading, financial, data, or business losses arising from use of the Service.</p><p>Your sole remedy is to stop using the Service.</p><h2 id="_10-privacy" tabindex="-1">10. Privacy <a class="header-anchor" href="#_10-privacy" aria-label="Permalink to &quot;10. Privacy&quot;">​</a></h2><p>Use of the Service is also governed by the <a href="/privacy">Privacy Policy</a>, which explains how data is collected, used, and shared.</p><h2 id="_11-refunds-and-cancellation" tabindex="-1">11. Refunds and Cancellation <a class="header-anchor" href="#_11-refunds-and-cancellation" aria-label="Permalink to &quot;11. Refunds and Cancellation&quot;">​</a></h2><p>Cancellation and refund handling is described in the <a href="/refund-policy">Refund and Cancellation Policy</a>. Payment-provider receipt, portal, or manage-subscription links may be used for subscription management and refund requests.</p><h2 id="_12-changes-to-these-terms" tabindex="-1">12. Changes to These Terms <a class="header-anchor" href="#_12-changes-to-these-terms" aria-label="Permalink to &quot;12. Changes to These Terms&quot;">​</a></h2><p>We may update these Terms from time to time. Continued use of TickerForge after changes are posted means you accept the revised Terms.</p><h2 id="_13-contact" tabindex="-1">13. Contact <a class="header-anchor" href="#_13-contact" aria-label="Permalink to &quot;13. Contact&quot;">​</a></h2><p>For questions about these Terms or the Service, contact:</p><p><strong>Email:</strong> <a href="mailto:support@ticker-forge.com" target="_blank" rel="noreferrer">support@ticker-forge.com</a></p>',45)]))}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
